# --------------------------------------------------------------------------- model builders
def _make_lr(C: float, random_state: int = config.LR_RANDOM_STATE):
    """L2 logistic regression, robust across scikit-learn versions.

    ``penalty='l2'`` is explicit (R3) but deprecated in scikit-learn >= 1.8 (removed in 1.10),
    where the equivalent is ``l1_ratio=0``.  We try the explicit form and fall back silently.
    """
    common = dict(
        C=C,
        solver=config.LR_SOLVER,
        max_iter=config.LR_MAX_ITER,
        fit_intercept=config.LR_FIT_INTERCEPT,
        random_state=random_state,
    )
    try:
        with warnings.catch_warnings():
            warnings.simplefilter("ignore", FutureWarning)
            return LogisticRegression(penalty=config.LR_PENALTY, **common)
    except TypeError:  # pragma: no cover - future sklearn
        return LogisticRegression(l1_ratio=0.0, **common)


def build_pipeline(C: float, random_state: int = config.LR_RANDOM_STATE) -> Pipeline:
    """MinMaxScaler + L2 logistic regression, as in the authors' ``example.py``."""
    return Pipeline([("scaler", MinMaxScaler()), ("classify", _make_lr(C, random_state))])

